#!/usr/bin/env bun
/**
 * Regenerates the embedded writing-kit snapshots used by `bradbit init`.
 *
 * Usage:
 *   bun run script/sync-kits.ts /path/to/guionista-kit /path/to/campaign-kit /path/to/libro-kit
 *
 * The generated file is committed so the CLI binary and the tests do not need
 * the kit repositories at build time.
 */

import { readdir, readFile, writeFile } from "node:fs/promises"
import path from "node:path"

const sources = process.argv.slice(2)
if (sources.length === 0) {
  console.error("Usage: bun run script/sync-kits.ts <kit-path>...")
  process.exit(2)
}

const output = path.resolve(import.meta.dir, "../src/kit/kits.generated.ts")
const ignored = new Set([".git", "exports", ".DS_Store", "node_modules"])

interface Manifest {
  id: string
  name: string
  version: string
  description: string
  author: string
  minimumBradbit: string
  contents: string[]
}

async function walk(directory: string, prefix = ""): Promise<Array<[string, string]>> {
  const entries = await readdir(directory, { withFileTypes: true })
  const files: Array<[string, string]> = []
  for (const entry of entries.toSorted((a, b) => a.name.localeCompare(b.name))) {
    if (ignored.has(entry.name)) continue
    const relative = prefix ? `${prefix}/${entry.name}` : entry.name
    const absolute = path.join(directory, entry.name)
    if (entry.isDirectory()) {
      files.push(...(await walk(absolute, relative)))
      continue
    }
    if (!entry.isFile()) continue
    files.push([relative, await readFile(absolute, "utf8")])
  }
  return files
}

const kits: Array<{ manifest: Manifest; files: Array<[string, string]> }> = []
for (const source of sources) {
  const root = path.resolve(source)
  const manifestPath = path.join(root, "bradbit-kit.json")
  const manifest = JSON.parse(await readFile(manifestPath, "utf8")) as Manifest
  if (!manifest.id || !manifest.name || !manifest.version) {
    throw new Error(`Invalid bradbit-kit.json in ${root}`)
  }
  if (kits.some((kit) => kit.manifest.id === manifest.id)) {
    throw new Error(`Duplicate kit id: ${manifest.id}`)
  }
  kits.push({ manifest, files: await walk(root) })
}

kits.sort((a, b) => a.manifest.id.localeCompare(b.manifest.id))

const lines = [
  "// Generated by packages/cli/script/sync-kits.ts. Do not edit by hand.",
  "// Source: the bradbit-kit repositories; the editor bundles the same files.",
  "export interface KitSnapshot {",
  "  id: string",
  "  name: string",
  "  version: string",
  "  description: string",
  "  author: string",
  "  minimumBradbit: string",
  "  contents: string[]",
  "  files: Record<string, string>",
  "}",
  "",
  "export const kits: Record<string, KitSnapshot> = {",
]
for (const { manifest, files } of kits) {
  lines.push(`  ${JSON.stringify(manifest.id)}: {`)
  lines.push(`    id: ${JSON.stringify(manifest.id)},`)
  lines.push(`    name: ${JSON.stringify(manifest.name)},`)
  lines.push(`    version: ${JSON.stringify(manifest.version)},`)
  lines.push(`    description: ${JSON.stringify(manifest.description)},`)
  lines.push(`    author: ${JSON.stringify(manifest.author)},`)
  lines.push(`    minimumBradbit: ${JSON.stringify(manifest.minimumBradbit)},`)
  lines.push(`    contents: ${JSON.stringify(manifest.contents)},`)
  lines.push("    files: {")
  for (const [relative, content] of files) {
    lines.push(`      ${JSON.stringify(relative)}: ${JSON.stringify(content)},`)
  }
  lines.push("    },")
  lines.push("  },")
}
lines.push("}")
lines.push("")
lines.push('export const guionistaKitFiles = kits["guionista-kit"].files')
lines.push("")

await writeFile(output, lines.join("\n"))
console.log(
  `Wrote ${kits.map((kit) => `${kit.manifest.id} (${kit.files.length})`).join(", ")} to ${path.relative(process.cwd(), output)}`,
)
